// はみ出しの見積もり (ファイル src/fit/estimate.ts) が、元の fitcheck.py と同じ文字を全角として数えるために使う。
// 範囲は、次の Python のコードで求めた (rs の要素が、下の配列の要素になる)。
//   import sys
//   import unicodedata
//
//   rs = []
//   s = None
//   for cp in range(0x110000):
