    // 一言の箱は幅 8.5 インチ・高さ 0.42 インチ・14 ポイントの太字
    assert.deepEqual(estimateSlides([{ key: "k", takeaway: ZENKAKU_10, elements: [] }]), []);
    const long = ZENKAKU_10.repeat(5);
